<template><q-page class="page"><div class="top"><q-btn flat round icon="arrow_back" to="/teacher/quizzes"/><div><span>QUIZ BUILDER</span><h1>{{ editing ? 'Edit quiz programme' : 'Create quiz programme' }}</h1></div><q-space/><q-btn unelevated no-caps icon="save" label="Save programme" :loading="saving" class="save" @click="save"/></div><q-card class="section"><q-card-section><h2>Programme details</h2><q-input v-model="form.title" outlined label="Quiz programme title" :rules="[v=>!!v?.trim()||'Title is required']"/></q-card-section></q-card><q-card class="section"><q-card-section><div class="section-title"><div><h2>Teams</h2><p>Add as many participating groups as needed.</p></div><q-btn flat no-caps icon="add" label="Add team" @click="addTeam"/></div><div class="team-grid"><q-input v-for="(team,i) in form.teams" :key="i" v-model="team.name" outlined :label="`Team ${i+1} name`"><template #append><q-btn v-if="form.teams.length>1" flat round dense icon="close" color="negative" @click="form.teams.splice(i,1)"/></template></q-input></div></q-card-section></q-card><q-card class="section"><q-card-section><div class="section-title"><div><h2>Questions</h2><p>Each question supports 4 or 5 answers and one correct answer.</p></div><q-btn flat no-caps icon="add" label="Add question" @click="addQuestion"/></div><q-expansion-item v-for="(q,qi) in form.questions" :key="qi" default-opened group="questions" :label="`Question ${qi+1}: ${q.question_text||'Untitled'}`" icon="help_outline" class="question"><div class="question-body"><div class="two"><q-input v-model="q.category" outlined label="Round / category"/><q-input v-model.number="q.time_seconds" type="number" min="15" outlined label="Timer (seconds)"/></div><q-input v-model="q.question_text" type="textarea" outlined label="Question"/><ImagePicker label="Question image (optional)" :path="q.image_path" @uploaded="q.image_path=$event" @removed="q.image_path=null"/><h3>Answers</h3><div v-for="(a,ai) in q.answers" :key="ai" class="answer"><q-radio v-model="q.correct" :val="ai"/><div class="answer-fields"><q-input v-model="a.answer_text" outlined dense :label="`Answer ${String.fromCharCode(65+ai)}`"/><ImagePicker label="Optional answer image" compact :path="a.image_path" @uploaded="a.image_path=$event" @removed="a.image_path=null"/></div><q-btn v-if="q.answers.length>4" flat round dense icon="delete" color="negative" @click="removeAnswer(q,ai)"/></div><div class="question-actions"><q-btn v-if="q.answers.length<5" flat no-caps icon="add" label="Add fifth answer" @click="addAnswer(q)"/><q-space/><q-btn v-if="form.questions.length>1" flat no-caps icon="delete" color="negative" label="Delete question" @click="form.questions.splice(qi,1)"/></div></div></q-expansion-item></q-card-section></q-card></q-page></template>
<script setup>
import { onMounted,reactive,ref } from 'vue'; import { useRoute,useRouter } from 'vue-router'; import { useQuasar } from 'quasar'; import { useQuizStore } from 'src/stores/quiz-store'; import ImagePicker from 'src/components/teacher/ImagePicker.vue';
const route=useRoute(),router=useRouter(),$q=useQuasar(),quiz=useQuizStore(),saving=ref(false),editing=Boolean(route.params.id)
const blankQuestion=()=>({category:'QUIZ ROUND',question_text:'',time_seconds:120,image_path:null,correct:0,answers:Array.from({length:4},()=>({answer_text:'',image_path:null}))})
const form=reactive({title:'',teams:[{name:'Team A',score:0}],questions:[blankQuestion()]})
const addTeam=()=>form.teams.push({name:`Team ${String.fromCharCode(65+form.teams.length)}`,score:0}); const addQuestion=()=>form.questions.push(blankQuestion()); const addAnswer=q=>q.answers.push({answer_text:'',image_path:null}); const removeAnswer=(q,i)=>{q.answers.splice(i,1);if(q.correct>=q.answers.length)q.correct=0}
onMounted(async()=>{if(editing){const d=await quiz.get(route.params.id);form.title=d.title;form.teams=d.teams.map(t=>({name:t.name,score:t.score}));form.questions=d.questions.map(q=>({...q,correct:q.answers.findIndex(a=>a.is_correct),answers:q.answers.map(a=>({...a}))}))}})
const save=async()=>{if(!form.title.trim())return $q.notify({type:'negative',message:'Enter a programme title'});if(form.teams.some(t=>!t.name.trim()))return $q.notify({type:'negative',message:'Every team needs a name'});for(const q of form.questions){if(!q.question_text.trim())return $q.notify({type:'negative',message:'Every question needs text'});if(q.answers.some(a=>!a.answer_text?.trim()&&!a.image_path))return $q.notify({type:'negative',message:'Every answer needs text or an image'})}saving.value=true;try{const payload={title:form.title,teams:form.teams,questions:form.questions.map(q=>({...q,answers:q.answers.map((a,i)=>({...a,is_correct:i===q.correct}))}))};if(editing)await quiz.update(route.params.id,payload);else await quiz.create(payload);$q.notify({type:'positive',message:'Quiz programme saved'});router.push('/teacher/quizzes')}catch(e){$q.notify({type:'negative',message:e.response?.data?.message||'Could not save quiz'})}finally{saving.value=false}}
</script>
<style scoped>.page{padding:32px clamp(15px,4vw,58px) 70px}.top{display:flex;align-items:center;gap:14px;margin-bottom:25px}.top span{color:#4770dc;font-size:.65rem;font-weight:900;letter-spacing:.11em}.top h1{margin:3px 0;font-size:1.75rem}.save{color:#fff;background:linear-gradient(110deg,#1677ff,#6745e8);border-radius:12px}.section{max-width:1000px;margin:18px auto;border:1px solid #e0e8f4;border-radius:20px;box-shadow:0 8px 24px rgba(20,52,108,.06)}.section .q-card__section{padding:25px}.section h2{margin:0 0 18px;font-size:1.2rem}.section-title{display:flex;justify-content:space-between;align-items:start}.section-title h2{margin-bottom:3px}.section-title p{margin:0 0 18px;color:#8492a8}.team-grid,.two{display:grid;grid-template-columns:repeat(2,1fr);gap:13px}.question{margin:12px 0;border:1px solid #dfe8f4;border-radius:14px;overflow:hidden}.question-body{padding:10px 20px 22px;display:grid;gap:14px}.question-body h3{margin:8px 0 0}.answer{display:flex;align-items:start;gap:8px}.answer-fields{display:grid;grid-template-columns:1fr 240px;gap:10px;flex:1}.question-actions{display:flex}@media(max-width:700px){.team-grid,.two,.answer-fields{grid-template-columns:1fr}.top{flex-wrap:wrap}.top .q-space{display:none}.save{margin-left:auto}}</style>
